"""Demo: verifying the walk-sum / shortest-walk identity for tropical powers."""
from __future__ import annotations
import itertools, math
from typing import List
INF = math.inf
Matrix = List[List[float]]

def trop_matmul(a: Matrix, b: Matrix) -> Matrix:
    n, m, p = len(a), len(b), len(b[0])
    return [[min(a[i][l] + b[l][j] for l in range(m)) for j in range(p)] for i in range(n)]

def trop_identity(n: int) -> Matrix:
    return [[0.0 if i == j else INF for j in range(n)] for i in range(n)]

def trop_matpow(a: Matrix, k: int) -> Matrix:
    n = len(a); result = trop_identity(n); base = [r[:] for r in a]; e = k
    while e > 0:
        if e & 1: result = trop_matmul(result, base)
        base = trop_matmul(base, base); e >>= 1
    return result

def shortest_kstep(a: Matrix, k: int, i: int, j: int) -> float:
    n = len(a); best = INF
    for interior in itertools.product(range(n), repeat=max(k - 1, 0)):
        path = (i,) + interior + (j,) if k >= 1 else (i,)
        w = 0.0 if (k == 0 and i == j) else (INF if k == 0 else sum(a[path[t]][path[t+1]] for t in range(k)))
        best = min(best, w)
    return best

if __name__ == "__main__":
    A = [[4.0, 1.0, INF], [INF, 3.0, 2.0], [1.0, INF, 5.0]]
    for k in range(5):
        P = trop_matpow(A, k)
        ok = all(P[i][j] == shortest_kstep(A, k, i, j) or (math.isinf(P[i][j]) and math.isinf(shortest_kstep(A, k, i, j)))
                 for i in range(3) for j in range(3))
        print(f"k={k}: (A^k)_ij equals shortest k-step walk weight -> {ok}")

"""Demo: tropical eigenvalue additivity lambda(A^k) = k*lambda(A) via minimum cycle mean."""
from __future__ import annotations
import math
from fractions import Fraction
from typing import List, Optional
INF = math.inf
Matrix = List[List[float]]

def trop_matmul(a: Matrix, b: Matrix) -> Matrix:
    n, m, p = len(a), len(b), len(b[0])
    return [[min(a[i][l] + b[l][j] for l in range(m)) for j in range(p)] for i in range(n)]

def trop_matpow(a: Matrix, k: int) -> Matrix:
    n = len(a); result = [[0.0 if i == j else INF for j in range(n)] for i in range(n)]
    base = [r[:] for r in a]; e = k
    while e > 0:
        if e & 1: result = trop_matmul(result, base)
        base = trop_matmul(base, base); e >>= 1
    return result

def min_cycle_mean(a: Matrix) -> Optional[Fraction]:
    n = len(a)
    d: List[List[Optional[Fraction]]] = [[None] * n for _ in range(n + 1)]
    d[0][0] = Fraction(0)
    for t in range(1, n + 1):
        for v in range(n):
            best = None
            for u in range(n):
                if d[t-1][u] is not None and not math.isinf(a[u][v]):
                    c = d[t-1][u] + Fraction(int(a[u][v]))
                    best = c if best is None or c < best else best
            d[t][v] = best
    lam = None
    for v in range(n):
        if d[n][v] is None: continue
        worst = None
        for t in range(n):
            if d[t][v] is not None:
                val = Fraction(d[n][v] - d[t][v], n - t)
                worst = val if worst is None or val > worst else worst
        if worst is not None and (lam is None or worst < lam): lam = worst
    return lam

if __name__ == "__main__":
    A = [[4.0, 1.0, INF], [INF, 3.0, 2.0], [1.0, INF, 5.0]]
    lam = min_cycle_mean(A)
    print("lambda(A) =", lam)
    for k in range(1, 7):
        print(f"k={k}: lambda(A^k)={min_cycle_mean(trop_matpow(A,k))}, k*lambda(A)={k*lam}")

"""Demo: breaking tropical Diffie-Hellman via the eigenvalue attack on the TDLP."""
from __future__ import annotations
import math
from fractions import Fraction
from typing import List, Optional
INF = math.inf
Matrix = List[List[float]]

def trop_matmul(a: Matrix, b: Matrix) -> Matrix:
    n, m, p = len(a), len(b), len(b[0])
    return [[min(a[i][l] + b[l][j] for l in range(m)) for j in range(p)] for i in range(n)]

def trop_matpow(a: Matrix, k: int) -> Matrix:
    n = len(a); result = [[0.0 if i == j else INF for j in range(n)] for i in range(n)]
    base = [r[:] for r in a]; e = k
    while e > 0:
        if e & 1: result = trop_matmul(result, base)
        base = trop_matmul(base, base); e >>= 1
    return result

def min_cycle_mean(a: Matrix) -> Optional[Fraction]:
    n = len(a)
    d: List[List[Optional[Fraction]]] = [[None] * n for _ in range(n + 1)]
    d[0][0] = Fraction(0)
    for t in range(1, n + 1):
        for v in range(n):
            best = None
            for u in range(n):
                if d[t-1][u] is not None and not math.isinf(a[u][v]):
                    c = d[t-1][u] + Fraction(int(a[u][v]))
                    best = c if best is None or c < best else best
            d[t][v] = best
    lam = None
    for v in range(n):
        if d[n][v] is None: continue
        worst = None
        for t in range(n):
            if d[t][v] is not None:
                val = Fraction(d[n][v] - d[t][v], n - t)
                worst = val if worst is None or val > worst else worst
        if worst is not None and (lam is None or worst < lam): lam = worst
    return lam

def eigenvalue_attack(a: Matrix, b: Matrix) -> Optional[int]:
    la, lb = min_cycle_mean(a), min_cycle_mean(b)
    if la is None or la == 0 or lb is None: return None
    r = lb / la
    return int(r) if r.denominator == 1 else None

if __name__ == "__main__":
    A = [[4.0, 1.0, INF], [INF, 3.0, 2.0], [1.0, INF, 5.0]]
    for secret in (7, 13, 100, 1000, 999983):
        B = trop_matpow(A, secret)
        rec = eigenvalue_attack(A, B)
        print(f"secret k={secret} -> recovered k={rec}  {'BROKEN' if rec==secret else 'failed'}")

