function TROP-MATPOW(A, k):
    R <- tropical identity (0 on diagonal, +inf off diagonal)
    B <- A
    while k > 0:
        if k is odd:
            R <- TROP-MATMUL(R, B)      # (min,+) product
        B <- TROP-MATMUL(B, B)
        k <- floor(k / 2)
    return R

function MIN-CYCLE-MEAN(A):
    d[0][0] <- 0; all other d[0][v] <- undefined
    for t = 1..n:
        for v = 1..n:
            d[t][v] <- min over u of ( d[t-1][u] + A[u][v] )
    lambda <- +infinity
    for v = 1..n with d[n][v] defined:
        m <- max over t in 0..n-1 of ( d[n][v] - d[t][v] ) / ( n - t )
        lambda <- min(lambda, m)
    return lambda

